{"python":"import re, json

def cell_parts(c):
    if isinstance(c, dict):
        v = c.get('value', c.get('text',''))
        x = c.get('x0', c.get('x', None))
        return v, x
    return c, None

def row_cells(row):
    if isinstance(row, dict):
        return row.get('cells', [])
    return row

# Patient-level clinical truth from Table S1
truth = {}
clinical_rows = tables['CTM2-15-e70534-s003.xls']['Sheet1'].rows
for i, row in enumerate(clinical_rows[3:], start=4):
    cells = row_cells(row)
    if len(cells) >= 14:
        sid, _ = cell_parts(cells[0])
        resp, _ = cell_parts(cells[13])
        m = re.match(r'ESC\d+', str(sid))
        if m and str(resp) in ('Good','Poor'):
            truth[m.group(0)] = {'truth': 1 if resp == 'Good' else 0,
                                'truth_ref': f'CTM2-15-e70534-s003.xls/Sheet1/R{i}C14',
                                'id_ref': f'CTM2-15-e70534-s003.xls/Sheet1/R{i}C1'}

# Locate a column explicitly labelled AUCsum in geometrically parsed supplementary tables
targets = {}  # file -> (x, sheet, row, col)
for fn, sheets in tables.items():
    for sh, obj in sheets.items():
        for ri, row in enumerate(obj.rows, start=1):
            cells = row_cells(row)
            for ci, c in enumerate(cells, start=1):
                v, x = cell_parts(c)
                if re.search(r'AUC\s*sum', str(v), re.I):
                    targets[fn] = (x, sh, ri, ci, str(v))

print('Clinical n:', len(truth), truth.keys())
print('AUCsum targets:', targets)

scores = {}
# Extract patient IDs and the numeric value nearest the AUCsum column x-coordinate
for fn, sheets in tables.items():
    if fn not in targets:
        continue
    tx, _, _, _, label = targets[fn]
    for sh, obj in sheets.items():
        for ri, row in enumerate(obj.rows, start=1):
            cells = row_cells(row)
            parsed = []
            for ci, c in enumerate(cells, start=1):
                v, x = cell_parts(c)
                parsed.append((ci, v, x))
            for ci, v, x in parsed:
                m = re.search(r'ESC(\d+)', str(v))
                if not m:
                    continue
                sid = 'ESC' + m.group(1)
                nums = []
                for nci, nv, nx in parsed:
                    try:
                        fv = float(str(nv).replace(',',''))
                    except Exception:
                        continue
                    if nx is not None and tx is not None:
                        nums.append((abs(float(nx)-float(tx)), nci, fv, nx))
                    else:
                        nums.append((abs(nci-targets[fn][3]), nci, fv, nx))
                if nums:
                    nums.sort(key=lambda z:z[0])
                    dist, nci, fv, nx = nums[0]
                    # PDF word columns are close together; reject a value if it is clearly another column
                    if tx is None or nx is None or dist <= 35:
                        scores[sid] = {'score': fv,
                                       'score_ref': f'{fn}/{sh}/R{ri}C{nci}',
                                       'id_ref': f'{fn}/{sh}/R{ri}C{ci}',
                                       'distance': dist}

print('Scores found:', len(scores))
for k in sorted(scores, key=lambda x:int(x[3:])):
    print(k, scores[k], 'truth=', truth.get(k))

records = []
for sid in sorted(set(truth) & set(scores), key=lambda x:int(x[3:])):
    records.append({
        'id': sid,
        'score': {'ref': scores[sid]['score_ref']},
        'truth': {'ref': truth[sid]['truth_ref'], 'map': {'Poor':0, 'Good':1}}
    })

ok = len(records) == 24
if ok:
    # Independent sanity check using cells dictionary when available
    correct = 0
    for rec in records:
        sid = rec['id']
